      {"t":"fill","q":"__ cold today.","p":"Hari ini dingin","a":["It's","It is"],"o":["Is","There's","This"],"why":"Posisi subjek diisi \"it\"."},
      {"t":"fill","q":"There __ a bank near here.","p":"Ada bank di dekat sini","a":["is"],"o":["are","have","be"],"why":"Satu bank, jadi \"is\"."},
      {"t":"fill","q":"__ there any seats?","p":"Masih ada kursi kosong?","a":["Are"],"o":["Is","Do","Have"],"why":"\"Seats\" bentuk jamak, jadi \"Are\"."},
      {"t":"type","p":"Hari ini panas","a":["It's hot today","It is hot today"],"hint":"it · hot · today — cuaca pakai it","x":["There's"],"why":"Untuk cuaca, kalimatnya diawali \"it\"."},
      {"t":"type","p":"Di sini ada kamar mandi?","a":["Is there a bathroom here","Is there a restroom here"],"hint":"is there · bathroom — ingat artikel","x":["the"],"why":"Satu kamar mandi yang baru ditanyakan, jadi artikel \"a\"."},
      {"t":"type","p":"Ada dua kamar","a":["There are two rooms"],"hint":"there are · two · room — bentuk jamak","x":["room"],"why":"Ada \"two\", jadi kata benda wajib bentuk jamak: \"rooms\"."}
