  PATTERNS: [
    ["Could you ~?","Permintaan sopan: \"Bisakah Anda…?\". Lebih halus daripada \"Can you\"; \"Tolong\" saja belum cukup sopan","Could you help me with this?","polite"],
    ["Would you mind ~ing?","Permintaan yang sangat sopan: \"Apakah Anda keberatan…?\". Jawaban \"No\" berarti \"tidak keberatan, silakan\"","Would you mind closing the window?","polite"],
    ["Can I get ~?","\"Minta…\" di toko dan restoran (paling umum dalam bahasa Inggris lisan Amerika)","Can I get a large latte?","polite"],
    ["I'd like ~","Versi sopan dari \"want\": \"Saya mau… / Saya pesan…\"","I'd like a window seat, please.","polite"],
    ["a / an + kata benda","Satu benda yang bisa dihitung dan baru disebut. \"an\" sebelum bunyi vokal. Pekerjaan juga wajib pakai artikel","I have an idea.","articles"],
    ["the + kata benda","Benda tertentu yang sudah sama-sama diketahui","Can you open the door?","articles"],
    ["I am / You are / She is","\"to be\": dipakai sebelum kata sifat, kata benda, dan tempat, walaupun bahasa Indonesia tidak memakai apa-apa","She is a nurse.","be"],
    ["Do you ~? / Does he ~?","Kalimat tanya dengan kata kerja biasa. Untuk he, she, it pakai \"does\"","Does he live here?","be"],
    ["don't / doesn't + V1","Kalimat negatif dengan kata kerja biasa. Jangan \"I not eat\"","I don't eat meat.","be"],
    ["he / she / it + kata kerja-s","Dalam Simple Present Tense, orang ketiga tunggal mendapat -s","My sister works at a hospital.","be"],
    ["be + -ing","Yang sedang terjadi sekarang (\"sedang\"), atau rencana dekat yang sudah pasti","I'm meeting Jake tonight.","tense"],
    ["V2 (-ed / tidak beraturan)","Kejadian yang sudah selesai. Kata kerjanya wajib berubah walaupun sudah ada \"yesterday\" (went, ate, saw…)","I went to Bandung last week.","tense"],
    ["will + V1","Keputusan saat itu juga, janji, atau perkiraan (\"akan\")","I'll call you later.","tense"],
    ["be going to + V1","Rencana yang sudah disiapkan sebelumnya","I'm going to visit my parents this weekend.","tense"],
    ["Have you ever ~?","Menanyakan pengalaman: \"Pernahkah kamu…?\"","Have you ever tried durian?","tense"],
    ["in + bulan / tahun / musim","Rentang waktu yang panjang","My birthday is in June.","prep"],
    ["on + hari / tanggal","Satu hari tertentu (\"pada hari Senin\")","The party is on Saturday.","prep"],
    ["at + jam / titik","Jam yang tepat atau satu titik tempat","Let's meet at 7 at the station.","prep"],
    ["How about ~ing?","Mengajak atau menawarkan: \"Bagaimana kalau…?\"","How about getting lunch together?","smalltalk"],
    ["So do I / Neither do I","\"Saya juga\" (positif) / \"Saya juga tidak\" (negatif). Santai: \"Me too\" / \"Me neither\"","I love this song. / So do I.","smalltalk"],
    ["kata kerja + it + partikel","Kalau objek phrasal verb berupa kata ganti, letaknya di tengah","Can you turn it down?","phrasal"],
    ["look forward to + -ing","\"to\" di sini preposisi, jadi diikuti bentuk -ing","I'm looking forward to hearing from you.","phrasal"],
    ["It's + jam","Menyebut jam: jam dan menitnya dibaca apa adanya","It's ten fifteen.","numbers"],
    ["I'm writing to ~","Kalimat pertama email: sebutkan tujuannya, pengganti \"Dengan hormat\"","I'm writing to confirm our meeting.","email"],
    ["Let me know if ~","\"Kabari saya kalau…\": penutup email yang umum","Let me know if you need anything else.","email"]
  ],
